 colStatus.setCellFactory(x->SemanticTableCells.status("document"));colPaymentStatus.setCellFactory(x->SemanticTableCells.status("payment"));if(colReturnStatus!=null)colReturnStatus.setCellFactory(x->SemanticTableCells.status("return"));colMail.setCellFactory(x->SemanticTableCells.status("email"));colDue.setCellFactory(x->SemanticTableCells.dueDate());
  tablePurchase.setRowFactory(tv->{TableRow<Purchase> row=new TableRow<>();row.setOnMouseClicked(e->{if(row.isEmpty()||e.getButton()!=javafx.scene.input.MouseButton.PRIMARY||e.getClickCount()!=1||RegisterUiSupport.isInteractiveTableTarget(e.getPickResult().getIntersectedNode(),row))return;Purchase clicked=row.getItem();if(detailDrawer.isVisible()&&selected!=null&&selected.getId()==clicked.getId())closeDetails();else{tablePurchase.getSelectionModel().select(clicked);details(clicked);}e.consume();});return row;});
