 private void applyDateRange(LocalDate from,LocalDate to){dpFrom.setValue(from);dpTo.setValue(to);filter();}
 @FXML private void saveCurrentView(){
  TextInputDialog d=new OwnedTextInputDialog();d.setTitle("Save Filter View");d.setHeaderText("Save the current purchase filters");d.setContentText("View name:");
  d.showAndWait().map(String::trim).filter(x->!x.isBlank()).ifPresent(name->{
   String data=String.join("|",s(cmbSupplier.getValue()),str(dpFrom.getValue()),str(dpTo.getValue()),s(cmbPaymentStatus.getValue()),s(cmbMailStatus.getValue()),s(cmbDocumentStatus.getValue()),s(txtSearch.getText()));
   Integer uid=SessionService.current()==null?null:SessionService.current().getId();
   UiTaskExecutor.submitAction("purchase-save-view",()->{support.saveView(uid,"PURCHASE_REGISTER",name,data);return true;},ignored->{org.example.util.ToastManager.success(tablePurchase,"Saved view created",name);},failure->error(failure instanceof Exception e?e:new RuntimeException(failure)));
  });
 }
 private MenuItem savedViewPlaceholder(){MenuItem i=new MenuItem("No saved views");i.getStyleClass().add("register-saved-view-item");i.setDisable(true);return i;}
 private void loadSavedViews(){if(savedViewsMenu==null)return;Integer uid=SessionService.current()==null?null:SessionService.current().getId();UiTaskExecutor.submitLatest("purchase-saved-views",()->support.savedViews("PURCHASE_REGISTER",uid),views->{savedViewsMenu.getItems().clear();for(SupportApiClient.SavedView v:views){MenuItem i=new MenuItem(v.name());i.getStyleClass().add("register-saved-view-item");i.setOnAction(e->applySaved(v.name(),v.data()));savedViewsMenu.getItems().add(i);}if(savedViewsMenu.getItems().isEmpty())savedViewsMenu.getItems().add(savedViewPlaceholder());},failure->{savedViewsMenu.getItems().setAll(savedViewPlaceholder());PerformanceMonitor.event("purchase-saved-views",String.valueOf(failure.getMessage()));});}
 private void applySaved(String name,String data){String[]x=data==null?new String[0]:data.split("\\|",-1);if(x.length==0){info("The saved view is empty and cannot be applied.");return;}searchDebouncer.cancel();applyingSavedView=true;try{String supplier=part(x,0);org.example.util.PartySearchUi.preserveSelection(cmbSupplier,supplier.isBlank()?"All Suppliers":supplier,"All Suppliers");dpFrom.setValue(parseDate(part(x,1)));dpTo.setValue(parseDate(part(x,2)));selectSaved(cmbPaymentStatus,part(x,3),"All");selectSaved(cmbMailStatus,part(x,4),"All");selectSaved(cmbDocumentStatus,part(x,5),"All");txtSearch.setText(part(x,6));pageState.reset();pendingSavedViewName=name;}finally{applyingSavedView=false;}searchDebouncer.cancel();reloadPage();}
 private void notifyAppliedSavedView(){if(pendingSavedViewName==null)return;String name=pendingSavedViewName;pendingSavedViewName=null;org.example.util.ToastManager.info(tablePurchase,"Saved view applied",name+" filters are now active.");}
 private static String part(String[] values,int index){return values!=null&&index>=0&&index<values.length&&values[index]!=null?values[index]:"";}
 private static void selectSaved(ComboBox<String> box,String raw,String fallback){if(box==null)return;String value=raw==null||raw.isBlank()?fallback:raw.trim();String match=box.getItems().stream().filter(v->v!=null&&v.equalsIgnoreCase(value)).findFirst().orElse(null);if(match==null&&!value.equalsIgnoreCase(fallback)){box.getItems().add(value);match=value;}box.setValue(match!=null?match:fallback);}
 private String str(LocalDate d){return d==null?"":d.toString();}
 private LocalDate parseDate(String d){try{return d==null||d.isBlank()?null:LocalDate.parse(d);}catch(Exception ignored){return null;}}
 @FXML private void toggleAdvanced(){advancedFilters.setManaged(btnAdvanced.isSelected());advancedFilters.setVisible(btnAdvanced.isSelected());}@FXML private void resetFilters(){txtSearch.clear();cmbSupplier.setValue("All Suppliers");cmbPaymentStatus.setValue("All");cmbMailStatus.setValue("All");cmbDocumentStatus.setValue("All");dpFrom.setValue(BusinessClock.today().minusMonths(6));dpTo.setValue(BusinessClock.today());filter();}
 @FXML private void newPurchase(){NavigationManager.navigateOrReport("/fxml/pages/Purchase.fxml");}
 private void edit(Purchase p){openPurchaseEditor(p,false);}
 private void view(Purchase p){openPurchaseEditor(p,true);}
 private void openPurchaseEditor(Purchase p,boolean viewOnly){
  try{
   FXMLLoader loader=new FXMLLoader(org.example.util.ResourceLocator.require("/fxml/pages/Purchase.fxml"));
   Parent root=loader.load();
   org.example.util.ProfessionalUiEnhancer.enhance(root);
   PurchaseController controller=loader.getController();
   Purchase full=service.getByInvoice(p.getInvoiceNo());
   if(full==null)throw new IllegalStateException("Purchase invoice "+p.getInvoiceNo()+" was not found. Refresh the register and try again.");
   controller.loadPurchase(full);
   if(viewOnly)controller.setViewMode(true);
   NavigationManager.getInstance().showPreparedPage("/fxml/pages/Purchase.fxml",root,controller);
  }catch(Exception e){error(e);}
 }
 private void details(Purchase p){selected=p;RegisterUiSupport.showDrawer(detailDrawer,mainSplit,.8);lblDetailInvoice.setText(p.getInvoiceNo());lblDetailSupplier.setText(p.getSupplier()==null?"Unknown Supplier":p.getSupplier().getName());lblDetailContact.setText(p.getSupplier()==null?"":s(p.getSupplier().getPhone())+"\n"+s(p.getSupplier().getEmail())+"\n"+s(p.getSupplier().getGstin()));lblDetailAmount.setText(fmt(p.getTotalAmount()));lblDetailPaid.setText(fmt(p.getPaidAmount()));lblDetailBalance.setText(fmt(p.getBalanceAmount()));lblDetailDue.setText(due(p));if(lblDetailGst!=null)lblDetailGst.setText(fmt(p.getGstAmount()));if(lblDetailReference!=null)lblDetailReference.setText(s(p.getReferenceNo()).isBlank()?"Not set":p.getReferenceNo());if(lblDetailPaymentTerms!=null)lblDetailPaymentTerms.setText(s(p.getPaymentTerms()).isBlank()?"Not set":p.getPaymentTerms());if(lblDetailContactPerson!=null)lblDetailContactPerson.setText(s(p.getContactPerson()).isBlank()?(p.getSupplier()==null||s(p.getSupplier().getContactPerson()).isBlank()?"Not set":p.getSupplier().getContactPerson()):p.getContactPerson());if(lblDetailPhone!=null)lblDetailPhone.setText(p.getSupplier()==null||s(p.getSupplier().getPhone()).isBlank()?"Not set":p.getSupplier().getPhone());if(lblDetailEmail!=null)lblDetailEmail.setText(p.getSupplier()==null||s(p.getSupplier().getEmail()).isBlank()?"Not set":p.getSupplier().getEmail());if(lblDetailGstin!=null)lblDetailGstin.setText(s(p.getBillingGstin()).isBlank()?(p.getSupplier()==null||s(p.getSupplier().getGstin()).isBlank()?"Not set":p.getSupplier().getGstin()):p.getBillingGstin());if(lblDetailCharges!=null)lblDetailCharges.setText(p.getCharges()==null||p.getCharges().isEmpty()?"Not Applicable":p.getCharges().stream().map(c->c.getChargeType()+" • "+fmt(c.getAmount())+(c.isTaxable()?" (GST "+String.format(java.util.Locale.ROOT,"%.2f%%",c.getGstPercent())+")":"")).collect(java.util.stream.Collectors.joining("\n")));if(lblDetailChargeTax!=null)lblDetailChargeTax.setText(fmt(p.getChargesTaxAmount()));if(lblDetailGstType!=null)lblDetailGstType.setText(s(p.getGstType()).isBlank()?"Not Applicable":p.getGstType());if(lblDetailTransporter!=null)lblDetailTransporter.setText(s(p.getTransporter()).isBlank()?"Not Applicable":p.getTransporter());if(lblDetailVehicle!=null)lblDetailVehicle.setText(s(p.getVehicleNumber()).isBlank()?"Not Applicable":p.getVehicleNumber());if(lblDetailNotes!=null)lblDetailNotes.setText(s(p.getNotes()).isBlank()?"No notes":p.getNotes());if(lblDetailAttachment!=null){int purchaseId=p.getId();lblDetailAttachment.setText("Loading attachments…");UiTaskExecutor.submitLatest("purchase-register-attachment-count",()->support.documentAttachments("PURCHASE",purchaseId).size(),count->{if(selected!=null&&selected.getId()==purchaseId)lblDetailAttachment.setText(AttachmentPreviewSupport.countLabel(count));},failure->{if(selected!=null&&selected.getId()==purchaseId)lblDetailAttachment.setText(s(p.getAttachmentPath()).isBlank()?"No attachments":"1 attachment");});}if(lblDetailBillingAddress!=null)lblDetailBillingAddress.setText(s(p.getBillingAddress()).isBlank()?"Not set":p.getBillingAddress());if(lblDetailDeliveryAddress!=null){String delivery=s(p.getDeliveryAddress());if(delivery.isBlank()&&p.isSameAsBilling())delivery=s(p.getBillingAddress());lblDetailDeliveryAddress.setText(delivery.isBlank()?"Not set":delivery);}boolean pendingApproval=isPendingApproval(p),admin=isAdmin();if(approvalActionBox!=null){approvalActionBox.setManaged(pendingApproval&&admin);approvalActionBox.setVisible(pendingApproval&&admin);}if(btnApprovePurchase!=null)btnApprovePurchase.setDisable(!pendingApproval||!admin);if(btnRejectPurchase!=null)btnRejectPurchase.setDisable(!pendingApproval||!admin);}
private void configureDetailsCloseButton(){
     if(btnCloseDetails == null) return;
     btnCloseDetails.setGraphic(IconFactory.icon("cancel"));
     btnCloseDetails.getProperties().put("erp-icon-preserve", true);
     btnCloseDetails.setAccessibleText("Close purchase details");
 }
 @FXML private void closeDetails(){selected=null;RegisterUiSupport.hideDrawer(detailDrawer,mainSplit,tablePurchase);}
 @FXML private void approveSelectedPurchase(){Purchase p=selected;if(p==null)return;try{service.approve(p.getInvoiceNo());NotificationService.add("Purchase "+p.getInvoiceNo()+" approved.");refresh();}catch(Exception e){error(e);}}
 @FXML private void rejectSelectedPurchase(){Purchase p=selected;if(p==null)return;OwnedTextInputDialog dialog=new OwnedTextInputDialog();dialog.setTitle("Reject Purchase");dialog.setHeaderText("Reject "+p.getInvoiceNo());dialog.setContentText("Reason:");dialog.showAndWait().map(String::trim).filter(v->!v.isBlank()).ifPresent(reason->{try{service.reject(p.getInvoiceNo(),reason);NotificationService.add("Purchase "+p.getInvoiceNo()+" rejected.");refresh();}catch(Exception e){error(e);}});}
 @FXML private void paySelected(){if(selected!=null)payment(selected);}
 @FXML private void editSelected(){if(selected!=null)edit(selected);}
 @FXML private void excelSelected(){if(selected!=null)excel(selected);}
 @FXML private void emailSelected(){if(selected!=null)email(selected);}
 private void payment(Purchase p){if(p==null)return;String document=s(p.getDocumentStatus()).trim().toUpperCase(java.util.Locale.ROOT);if(java.util.Set.of("PENDING APPROVAL","REJECTED").contains(document)){info("Admin approval is required before opening payments for this Purchase.");return;}if("DRAFT".equals(document)){info("Post the Purchase before opening payments.");return;}if(java.util.Set.of("DELETED","CANCELLED").contains(document)){info("Payments are unavailable for deleted or cancelled purchases.");return;}PurchaseScreenContext.select(p.getInvoiceNo());NavigationManager.getInstance().loadPage("/fxml/pages/PurchasePayment.fxml");}
 private void pdf(Purchase p){try{Purchase full=requirePurchase(p);java.awt.Desktop.getDesktop().open(InvoicePdfService.purchase(full).toFile());}catch(Exception e){error(e);}}
 private void excel(Purchase p){try{Purchase full=requirePurchase(p);Path file=ExcelOutputService.purchase(full);if(java.awt.Desktop.isDesktopSupported())java.awt.Desktop.getDesktop().open(file.toFile());else info("Excel file created: "+file);}catch(Exception e){error(e);}}
 private void email(Purchase p){if(isApprovalLocked(p)){info("Approve this Purchase before sending it externally.");return;}String stage="loading the purchase invoice";String recipient="";try{Purchase full=requirePurchase(p);if(full.getSupplier()==null)throw new IllegalStateException("No supplier is linked to "+full.getInvoiceNo()+".");recipient=s(full.getSupplier().getEmail()).trim();if(recipient.isBlank())throw new IllegalStateException("Supplier email is missing for "+full.getSupplier().getName()+". Update Supplier Master and try again.");stage="generating the purchase invoice PDF";Path pdf=InvoicePdfService.purchase(full);stage="sending the email";EmailService.send(recipient,"Purchase Invoice "+full.getInvoiceNo(),"Dear "+s(full.getSupplier().getName())+",\n\nPlease find the purchase invoice attached.\n\nRegards,\n"+org.example.config.ConfigManager.get("company.name","DSE ERP"),pdf);service.markEmailSent(full.getId());logCommunication(full.getId(),recipient,"Purchase Invoice "+full.getInvoiceNo(),"SENT",null);refresh();info("Email sent successfully to "+recipient+".");}catch(Exception failure){logCommunication(p.getId(),recipient,"Purchase Invoice "+p.getInvoiceNo(),"FAILED",stage+": "+rootMessage(failure));error(new IllegalStateException("Email failed while "+stage+".\n\n"+rootMessage(failure),failure));}}
 private Purchase requirePurchase(Purchase row){Purchase full=service.getByInvoice(row.getInvoiceNo());if(full==null)throw new IllegalStateException("Purchase invoice "+row.getInvoiceNo()+" was not found. Refresh the register and try again.");return full;}
 private void logCommunication(int id,String recipient,String subject,String status,String error){try{support.communication(new SupportApiClient.CommunicationRequest("PURCHASE",id,"EMAIL",recipient,subject,status,error,user()));}catch(Exception ignored){}}
 private String rootMessage(Throwable failure){Throwable root=failure;while(root.getCause()!=null)root=root.getCause();String message=root.getMessage();return message==null||message.isBlank()?root.getClass().getSimpleName():message;}
 private void whatsapp(Purchase p){if(isApprovalLocked(p)){info("Approve this Purchase before sharing it externally.");return;}try{Purchase full=service.getByInvoice(p.getInvoiceNo());String phone=s(full.getSupplier().getPhone()).replaceAll("\\D","");if(phone.length()==10)phone="91"+phone;if(phone.isBlank())throw new IllegalStateException("Supplier mobile number is missing. Update it in Supplier Master.");Path pdf=InvoicePdfService.purchase(full);WhatsappService.openWhatsappWithMessage(phone,PaymentMessageService.purchaseMessage(full),pdf,PaymentMessageService.configuredQrPath());support.communication(new SupportApiClient.CommunicationRequest("PURCHASE",full.getId(),"WHATSAPP",phone,"Purchase Invoice "+full.getInvoiceNo(),"SENT",null,user()));refresh();info("WhatsApp is ready. The purchase PDF and configured UPI QR are on the clipboard for attachment.");}catch(Exception e){error(e);}}
 private void delete(Purchase p){if(isFinanciallyLocked(p)){info("Paid, partially paid, or settled purchases cannot be deleted. Create a purchase return instead.");return;}String status=s(p.getDocumentStatus()).trim().toUpperCase(java.util.Locale.ROOT);if("DELETED".equals(status)){info("This purchase is already marked as deleted.");return;}String prompt="Delete "+p.getInvoiceNo()+"?\n\nThe document will disappear from the normal Purchase Register, but its backend audit record will be retained as DELETED.\nAny inventory movement already posted by this purchase will be reversed safely.";if(new OwnedAlert(Alert.AlertType.CONFIRMATION,prompt,ButtonType.YES,ButtonType.NO).showAndWait().orElse(ButtonType.NO)!=ButtonType.YES)return;try{service.delete(p.getInvoiceNo());refresh();closeDetails();info(p.getInvoiceNo()+" deleted from the register. Backend audit record retained.");}catch(Exception e){error(e);}}
 private void duplicate(Purchase p){try{FXMLLoader l=new FXMLLoader(org.example.util.ResourceLocator.require("/fxml/pages/Purchase.fxml"));Parent root=l.load();org.example.util.ProfessionalUiEnhancer.enhance(root);PurchaseController c=l.getController();c.loadPurchase(service.getByInvoice(p.getInvoiceNo()));c.prepareDuplicate();NavigationManager.getInstance().showPreparedPage("/fxml/pages/Purchase.fxml",root,c);}catch(Exception e){error(e);}}

 private void notes(Purchase p){TextInputDialog d=new OwnedTextInputDialog(p.getNotes());d.setHeaderText("Notes / Remarks • "+p.getInvoiceNo());d.showAndWait().ifPresent(v->{try{support.notes("PURCHASE",p.getId(),v);refresh();}catch(Exception e){error(e);}});}
 private void cancelPurchase(Purchase p){if(p==null)return;String status=s(p.getDocumentStatus()).trim().toUpperCase(java.util.Locale.ROOT);if("CANCELLED".equals(status)){info("This purchase is already cancelled.");return;}if("DELETED".equals(status)){info("Deleted purchases cannot be cancelled.");return;}if(isFinanciallyLocked(p)){info("Paid, partially paid, or settled purchases cannot be cancelled. Create a purchase return instead.");return;}String prompt="Cancel "+p.getInvoiceNo()+"?\n\nThe document will remain visible with status CANCELLED and any posted inventory will be reversed safely.";if(new OwnedAlert(Alert.AlertType.CONFIRMATION,prompt,ButtonType.YES,ButtonType.NO).showAndWait().orElse(ButtonType.NO)!=ButtonType.YES)return;try{service.cancel(p.getInvoiceNo());refresh();closeDetails();info(p.getInvoiceNo()+" cancelled. The document remains visible in the register.");}catch(Exception e){error(e);}}
 private void createReturn(Purchase p){String document=s(p.getDocumentStatus()).toUpperCase(java.util.Locale.ROOT);if(java.util.Set.of("PENDING APPROVAL","REJECTED").contains(document)){info("Admin approval is required before creating a Purchase Return.");return;}if("DRAFT".equals(document)){info("Post the Purchase before creating a Purchase Return.");return;}if("DELETED".equals(document)||"CANCELLED".equals(document)){info("Deleted or cancelled purchases cannot create a Purchase Return.");return;}Purchase full=service.getByInvoice(p.getInvoiceNo());if(full==null){info("Purchase invoice not found. Refresh and try again.");return;}List<ReturnEditorService.InvoiceItem> items=full.getLines().stream().map(line->new ReturnEditorService.InvoiceItem(line.getItemCode(),line.getItemDescription(),line.getQuantity(),line.getRate(),line.getDiscountPercent(),line.getGstPercent())).toList();ReturnEditorService.show(tablePurchase.getScene().getWindow(),ReturnEditorService.Type.PURCHASE,p.getInvoiceNo(),p.getSupplier().getName(),p.getSupplier().getId(),items).ifPresent(no->{refresh();info("Purchase return created: "+no);});}
 @FXML private void exportPurchase(){org.example.service.PermissionService.require("PURCHASE.EXPORT", "Export Purchases");File f=choose("Purchase_Register.xlsx","Excel","*.xlsx");if(f==null)return;String supplier=cmbSupplier.getValue();if(supplier!=null&&supplier.startsWith("All"))supplier="";String selectedSupplier=supplier,q=txtSearch.getText(),payment=cmbPaymentStatus.getValue(),dueFilter="All",mail=cmbMailStatus.getValue(),documentStatus=cmbDocumentStatus.getValue();LocalDate from=dpFrom.getValue(),to=dpTo.getValue();UiTaskExecutor.submitAction("purchase-register-export-excel",()->{List<Purchase> rows=service.allFiltered(q,selectedSupplier,from,to,payment,dueFilter,mail,documentStatus);writePurchaseExcel(f,rows);return rows.size();},count->info("Purchase register exported • "+count+" records."),this::error);}
 @FXML private void exportPdf(){org.example.service.PermissionService.require("PURCHASE.EXPORT", "Export Purchases");File f=choose("Purchase_Register.pdf","PDF","*.pdf");if(f==null)return;String supplier=cmbSupplier.getValue();if(supplier!=null&&supplier.startsWith("All"))supplier="";String selectedSupplier=supplier,q=txtSearch.getText(),payment=cmbPaymentStatus.getValue(),dueFilter="All",mail=cmbMailStatus.getValue(),documentStatus=cmbDocumentStatus.getValue();LocalDate from=dpFrom.getValue(),to=dpTo.getValue();UiTaskExecutor.submitAction("purchase-register-export-pdf",()->{List<Purchase> rows=service.allFiltered(q,selectedSupplier,from,to,payment,dueFilter,mail,documentStatus);org.example.service.BrandedRegisterPdfService.export(f.toPath(),"Purchase Register",new String[]{"Invoice","Date","Supplier","Amount","Paid","Pending","Due","Document Status","Payment Status"},rows.stream().map(x->new String[]{x.getInvoiceNo(),BusinessClock.formatDate(x.getInvoiceDate()),x.getSupplier()==null?"":s(x.getSupplier().getName()),exportMoney(x.getTotalAmount()),exportMoney(x.getPaidAmount()),exportMoney(x.getBalanceAmount()),due(x),documentStatus(x),paymentStatusDisplay(x)}).toList(),new float[]{2,1.3f,2.4f,1.3f,1.3f,1.3f,1.5f,1.5f,1.6f});return rows.size();},count->info("Purchase register PDF exported • "+count+" records."),this::error);}
 private void writePurchaseExcel(File f,List<Purchase> rows)throws Exception{try(Workbook w=new XSSFWorkbook();FileOutputStream o=new FileOutputStream(f)){Sheet sh=w.createSheet("Purchases");String[]h={"Invoice","Date","Supplier","Amount","Paid","Pending","Due","Document Status","Payment Status","Email"};Row r=sh.createRow(0);for(int i=0;i<h.length;i++)r.createCell(i).setCellValue(h[i]);int n=1;for(Purchase x:rows){r=sh.createRow(n++);String[]v={x.getInvoiceNo(),BusinessClock.formatDate(x.getInvoiceDate()),x.getSupplier()==null?"":s(x.getSupplier().getName()),String.valueOf(x.getTotalAmount()),String.valueOf(x.getPaidAmount()),String.valueOf(x.getBalanceAmount()),due(x),documentStatus(x),paymentStatusDisplay(x),x.isEmailSent()?"Sent":"Not Sent"};for(int i=0;i<v.length;i++)r.createCell(i).setCellValue(v[i]);}w.write(o);}}
 private String exportMoney(double value){return NumberFormat.getCurrencyInstance(Locale.of("en","IN")).format(value).replace("₹","₹ ");}


 private boolean isAdmin(){return SessionService.isAdmin();}
 private boolean isPendingApproval(Purchase p){return p!=null&&"PENDING APPROVAL".equalsIgnoreCase(s(p.getDocumentStatus()).trim());}
 private boolean isApprovalLocked(Purchase p){if(p==null)return false;String status=s(p.getDocumentStatus()).trim().toUpperCase(java.util.Locale.ROOT);return status.equals("PENDING APPROVAL")||status.equals("REJECTED");}
 private String paymentStatusDisplay(Purchase p){if(p==null)return"";String status=s(p.getPaymentStatus()).trim().toUpperCase(java.util.Locale.ROOT);if("RETURN APPROVAL PENDING".equals(status))return"Return Pending Approval";if("RETURN PAID".equals(status))return"Return Paid";if("RETURN PARTIAL".equals(status))return"Return Partial";if("RETURN PENDING".equals(status))return"Return Pending";return status;}
 private boolean isFinanciallyLocked(Purchase p){if(p==null)return false;String payment=s(p.getBasePaymentStatus()).toUpperCase(java.util.Locale.ROOT);return p.getPaidAmount()>.009||payment.contains("PAID")||payment.contains("SETTLED")||payment.contains("PARTIAL");}
 private boolean isFullyPaid(Purchase p){if(p==null)return false;String payment=s(p.getBasePaymentStatus()).trim().toUpperCase(java.util.Locale.ROOT);return payment.equals("PAID")||payment.equals("SETTLED")||p.getPaidAmount()+.009>=p.getTotalAmount();}
 private boolean isReturnEligible(Purchase p){if(p==null||!isFullyPaid(p))return false;String document=s(p.getDocumentStatus()).trim().toUpperCase(java.util.Locale.ROOT);String current=s(p.getPaymentStatus()).trim().toUpperCase(java.util.Locale.ROOT);return "APPROVED".equals(document)&&!java.util.Set.of("RETURN APPROVAL PENDING","RETURN PENDING","RETURN PARTIAL").contains(current);}
 private boolean isActiveFinancialDocument(Purchase p){String document=s(p.getDocumentStatus()).toUpperCase(java.util.Locale.ROOT);return !document.contains("CANCEL")&&!document.contains("DELETE")&&!"DRAFT".equals(document);}
 private File choose(String n,String l,String x){FileChooser c=new FileChooser();c.setInitialFileName(n);c.getExtensionFilters().add(new FileChooser.ExtensionFilter(l,x));return c.showSaveDialog(tablePurchase.getScene().getWindow());}private String due(Purchase p){String document=s(p.getDocumentStatus()).toUpperCase(java.util.Locale.ROOT);if(document.contains("DELETE"))return"Deleted";if(document.contains("CANCEL"))return"Cancelled";String status=s(p.getPaymentStatus()).toUpperCase(java.util.Locale.ROOT);if("RETURN APPROVAL PENDING".equals(status))return"Awaiting Approval";if("RETURN PAID".equals(status))return"Settled";if("RETURN PENDING".equals(status)||"RETURN PARTIAL".equals(status)){LocalDate due=p.getReturnDueDate();if(due==null)return"Return Due";long d=java.time.temporal.ChronoUnit.DAYS.between(BusinessClock.today(),due);return d<0?"Return Overdue by "+Math.abs(d)+" days":d==0?"Return Due Today":"Return Due in "+d+" Days";}if(p.getBalanceAmount()<=.01)return"Settled";if(p.getDueDate()==null)return"Not set";long d=java.time.temporal.ChronoUnit.DAYS.between(BusinessClock.today(),p.getDueDate());return d<0?"Overdue by "+Math.abs(d)+" days":d==0?"Due today":"Due in "+d+" days";}private String fmt(double v){return money.format(v).replace("₹","₹ ");}private String s(String v){return v==null?"":v;}private String user(){return SessionService.current()==null?"System":SessionService.current().getFullName();}private void info(String m){org.example.util.ToastManager.success(tablePurchase,"Completed",m);}private void error(Throwable e){e.printStackTrace();String message=e.getMessage()==null?"Operation failed":e.getMessage();org.example.util.ModernDialog.error(tablePurchase,"Operation failed","Something went wrong",message);}


    private void applyRangeButtonIcons() {
        applyIcon(btnAllDatesRange,"calendar"); applyIcon(btnTodayRange,"calendar"); applyIcon(btnYesterdayRange,"history");
        applyIcon(btnSevenDaysRange,"calendar"); applyIcon(btnThirtyDaysRange,"calendar"); applyIcon(btnCustomRange,"calendar");
    }
    private void applyIcon(ButtonBase b,String semantic){ if(b!=null){b.setGraphic(IconFactory.compactIcon(semantic,15));b.getProperties().put("erp-icon-preserve",true);} }
 @Override public void onScreenShown(boolean reusedFromCache){org.example.shortcut.ShortcutRegistry.bindLabel(btnNewPurchase,org.example.shortcut.ShortcutRegistry.Action.NEW_PURCHASE,"Create Purchase");org.example.util.OperationalUiSupport.focusWorkArea(tablePurchase);if(ImportViewContext.consume("Purchases")){dpFrom.setValue(BusinessClock.today().minusYears(20));dpTo.setValue(BusinessClock.today());pageState.reset();reloadPage();return;}if(!reusedFromCache)return;if(ScreenRefreshPolicy.shouldRefresh("purchase-register",ScreenRefreshPolicy.Mode.WHEN_STALE))refresh();}
